34.         /// Initializes a new instance of the <see cref="ClientDiagnostics"/> class.
35.         /// </summary>
36.         /// <param name="optionsNamespace">Namespace of the client class, such as Azure.Storage or Azure.AppConfiguration.</param>
37.         /// <param name="providerNamespace">Azure Resource Provider namespace of the Azure service SDK is primarily used for.</param>
38.         /// <param name="diagnosticsOptions">The customer provided client diagnostics options.</param>
39.         /// <param name="suppressNestedClientActivities">Flag controlling if <see cref="System.Diagnostics.Activity"/>
40.         ///  created by this <see cref="ClientDiagnostics"/> for client method calls should be suppressed when called
41.         ///  by other Azure SDK client methods.  It's recommended to set it to true for new clients, use default (null) for old clients
42.         ///  for backward compatibility reasons, or set it to false to explicitly disable suppression for specific cases.
43.         ///  The default value could change in the future, the flag should be only set to false if suppression for the client
44.         ///  should never be enabled.</param>
45.         public ClientDiagnostics(string optionsNamespace, string? providerNamespace, DiagnosticsOptions diagnosticsOptions, bool? suppressNestedClientActivities = null)
46.             : base(optionsNamespace, providerNamespace, diagnosticsOptions.IsDistributedTracingEnabled, suppressNestedClientActivities.GetValueOrDefault(true), true)
47.         {
48.         }
