57.         internal static string? GetResourceProviderNamespace(Assembly assembly)
58.         {
59.             foreach (var customAttribute in assembly.GetCustomAttributesData())
60.             {
61.                 // Weak bind internal shared type
62.                 Type attributeType = customAttribute.AttributeType!;
63.                 if (attributeType.FullName == ("Azure.Core.AzureResourceProviderNamespaceAttribute"))
64.                 {
65.                     IList<CustomAttributeTypedArgument> namedArguments = customAttribute.ConstructorArguments;
